contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address staker, address rewardToken, uint256 stakeAmount, uint256 rewardAmount, uint256 distributorSeed) public {
        require(staker != address(0), "staker zero");
        require(rewardToken != address(0), "token zero");
        require(stakeAmount > 0, "stake zero");
        require(rewardAmount > 0, "reward zero");

        c.addReward(rewardToken);

        c.setRewardDistributor(address(this));

        c.notifyRewardAmount(rewardToken, rewardAmount);

        IERC20(rewardToken).approve(address(c), rewardAmount);

        c.stake(stakeAmount);

        uint256 balanceBefore = IERC20(rewardToken).balanceOf(staker);
        uint256 contractBalanceBefore = IERC20(rewardToken).balanceOf(address(c));

        c.getRewards(staker);

        uint256 balanceAfter = IERC20(rewardToken).balanceOf(staker);
        uint256 contractBalanceAfter = IERC20(rewardToken).balanceOf(address(c));
        uint256 claimableAfter = c.claimableRewards(staker, rewardToken);

        assert(balanceAfter >= balanceBefore && claimableAfter == 0 && (balanceAfter - balanceBefore) <= contractBalanceBefore && contractBalanceBefore - contractBalanceAfter == balanceAfter - balanceBefore);
    }
}

