contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        require(amount != 0 && amount <= 1000 ether, "bad amount");

        c.addReward(address(this));

        c.approve(address(c), amount);

        uint256 balBeforeTest = c.balanceOf(address(this));
        uint256 tsBefore = c.totalSupply();
        uint256 cBalBefore = c.balanceOf(address(c));

        c.stake(amount);

        uint256 balAfterStake = c.balanceOf(address(this));
        uint256 tsAfterStake = c.totalSupply();
        uint256 cBalAfterStake = c.balanceOf(address(c));

        uint256 withdrawBalBefore = c.balanceOf(address(this));
        uint256 withdrawTsBefore = c.totalSupply();
        uint256 withdrawCBalBefore = c.balanceOf(address(c));

        bool reverted;
        try c.withdraw(amount, false) { reverted = false; } catch { reverted = true; }

        uint256 withdrawBalAfter = c.balanceOf(address(this));
        uint256 withdrawTsAfter = c.totalSupply();
        uint256 withdrawCBalAfter = c.balanceOf(address(c));

        require(!reverted, "withdraw unexpectedly reverted");

        assert(
            balAfterStake == balBeforeTest + amount &&
            tsAfterStake == tsBefore + amount &&
            cBalAfterStake == cBalBefore + amount &&
            withdrawBalAfter == withdrawBalBefore - amount &&
            withdrawTsAfter == withdrawTsBefore - amount &&
            withdrawCBalAfter == withdrawCBalBefore - amount
        );
    }

    function approve(address spender, uint256 amount) external {
        require(msg.sender == address(c), "only staking token can approve");
        _allowance[msg.sender][spender] = amount;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balance[account];
    }

    mapping(address => mapping(address => uint256)) private _allowance;
    mapping(address => uint256) private _balance;
}

