contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        // Work with a positive amount only, then the effect is deterministic.
        require(amount > 0);

        // Make sure this test contract holds enough staking tokens to transfer.
        IERC20 stakingToken = c.stakingToken();

        // Snapshot the observable before-values.
        uint256 cBalanceBefore = stakingToken.balanceOf(address(c));
        uint256 supplyBefore = c.totalSupply();

        // Approve and stake on behalf of the test contract for `amount`.
        stakingToken.approve(address(c), amount);

        // The deciding state-changing call.
        bool reverted;
        try c.stake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, re-read the observables.
        uint256 cBalanceAfter = stakingToken.balanceOf(address(c));
        uint256 supplyAfter = c.totalSupply();

        // General rule: if the positive stake did not revert, then the contract's
        // staking-token balance increased by exactly `amount` and totalSupply increased
        // by exactly `amount`. (Express the first part without subtraction to avoid underflow.)
        assert(
            reverted ||
            (cBalanceAfter == cBalanceBefore + amount && supplyAfter == supplyBefore + amount)
        );
    }

    receive() external payable {}
}

