contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amountA, uint256 amountB) public {
        require(amountA > 0 && amountB > 0);
        require(amountA <= 1e27 && amountB <= 1e27);

        address stakingToken = address(c.stakingToken());
        require(stakingToken != address(0));

        address thisAddr = address(this);
        address aAddr = address(uint160(uint256(keccak256("a"))));
        address bAddr = address(uint160(uint256(keccak256("b"))));
        require(aAddr != thisAddr && bAddr != thisAddr && aAddr != bAddr);

        uint256 thisBal = IERC20(stakingToken).balanceOf(thisAddr);
        if (thisBal < amountA + amountB) { return; }

        require(IERC20(stakingToken).transfer(aAddr, amountA));
        require(IERC20(stakingToken).transfer(bAddr, amountB));

        uint256 aBal = IERC20(stakingToken).balanceOf(aAddr);
        uint256 bBal = IERC20(stakingToken).balanceOf(bAddr);
        require(aBal >= amountA);
        require(bBal >= amountB);

        uint256 beforeStake = IERC20(stakingToken).balanceOf(thisAddr);

        c.stakeFor(aAddr, aBal);

        uint256 midSupply = c.totalSupply();
        uint256 midA = c.balanceOf(aAddr);
        uint256 midB = c.balanceOf(bAddr);

        require(midSupply == midA + midB);
        require(IERC20(stakingToken).balanceOf(thisAddr) <= beforeStake);

        c.stakeFor(bAddr, bBal);

        uint256 endSupply = c.totalSupply();
        uint256 endA = c.balanceOf(aAddr);
        uint256 endB = c.balanceOf(bAddr);

        assert(endSupply == endA + endB && endA >= midA && endB >= midB);
    }

    receive() external payable {}
}

