contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 stakeAmount, uint256 withdrawAmount, bool claim) public {
        require(stakeAmount > 0);
        require(withdrawAmount > 0);

        // Get enough staking tokens from the contract's own balance to stake.
        c.stakingToken().transfer(address(this), stakeAmount);
        c.stakingToken().approve(address(c), stakeAmount);

        c.stakeFor(address(this), stakeAmount);

        uint256 beforeBalance = c.stakingToken().balanceOf(address(this));

        if (withdrawAmount > stakeAmount) {
            bool reverted;
            try c.withdraw(withdrawAmount, claim) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted || withdrawAmount <= c.totalSupply());
        } else {
            c.withdraw(withdrawAmount, claim);
            uint256 afterBalance = c.stakingToken().balanceOf(address(this));
            assert(afterBalance - beforeBalance == withdrawAmount);
        }
    }
}

