    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public payable {
        // We need a positive amount to stake, and try to withdraw more than staked.
        require(stakeAmount > 0 && withdrawAmount > stakeAmount);

        // No Ether is needed for staking/withdrawing in this contract.

        // Read the caller's staking-token balance and approve enough.
        // Use only the public surface of c and other existing contracts.
        IERC20 st = c.stakingToken();
        uint256 bal = st.balanceOf(address(this));
        // The test cannot conjure tokens; only run if it actually holds enough.
        require(bal >= stakeAmount);

        st.approve(address(c), stakeAmount);

        // State-changing calls are top-level statements.
        c.stake(stakeAmount);

        uint256 beforeBal = c.balanceOf(address(this));
        require(beforeBal == stakeAmount);

        bool reverted;
        try c.withdraw(withdrawAmount, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = c.balanceOf(address(this));

        // General rule: an over-withdrawal must revert and must not alter the staked balance.
        assert(reverted && afterBal == beforeBal);
    }

    receive() external payable {}
}

