contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, bool asOwner) public {
        require(rewardToken != address(0));

        bool ownerIsSender = (msg.sender == c.owner());
        require(asOwner == ownerIsSender);

        uint256 beforeLen = c.rewardTokens.length;
        bool tokenIsNew = true;
        uint256 i;
        for (i = 0; i < beforeLen; i++) {
            if (c.rewardTokens(i) == rewardToken) {
                tokenIsNew = false;
            }
        }

        bool reverted;
        try c.addReward(rewardToken) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (msg.sender != c.owner()) {
            assert(reverted);
            assert(c.rewardTokens.length == beforeLen);
        } else {
            assert(!reverted == tokenIsNew);
            if (!reverted) {
                assert(c.rewardTokens.length == beforeLen + 1);
                assert(c.rewardTokens(beforeLen) == rewardToken);
            } else {
                assert(!tokenIsNew);
                assert(c.rewardTokens.length == beforeLen);
            }
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 existingIndex) public {
        require(rewardToken != address(0));

        bool ownerIsSender = (msg.sender == c.owner());

        // Read initial token count via a known token index loop is not possible without length;
        // use the fact that rewardTokens is public with uint256 index and try reading index 0..
        // We cannot know length, so we detect registration dynamically.

        // Check whether token already registered by scanning indices 0..existingIndex
        bool tokenIsNew = true;
        for (uint256 i = 0; i <= existingIndex; i++) {
            address t;
            try c.rewardTokens(i) returns (address _t) {
                t = _t;
            } catch {
                break;
            }
            if (t == rewardToken) {
                tokenIsNew = false;
                break;
            }
        }

        bool reverted;
        try c.addReward(rewardToken) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!ownerIsSender) {
            assert(reverted);
        } else {
            assert(!reverted == tokenIsNew);
        }
    }
}

