        IERC20 token = c.stakingToken();
        require(token.transferFrom(msg.sender, address(this), stakeAmount), "transferFrom failed");
        require(token.approve(address(c), stakeAmount), "approve failed");

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));

        c.stakeFor(address(this), stakeAmount);

        // After a successful stake of stakeAmount, totalSupply and the staker's balance
        // must each have increased by exactly stakeAmount.
        uint256 supplyAfterStake = c.totalSupply();
        uint256 balanceAfterStake = c.balanceOf(address(this));
        assert(supplyAfterStake == supplyBefore + stakeAmount && balanceAfterStake == balanceBefore + stakeAmount);

        // Attempt a withdraw that is strictly larger than the staker's balance; this must revert.
        bool reverted;
        try c.withdraw(balanceAfterStake + withdrawAmount + 1, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // A withdrawal larger than the held balance must revert and must leave both the
        // staker's balance and totalSupply unchanged.
        assert(reverted && c.balanceOf(address(this)) == balanceAfterStake && c.totalSupply() == supplyAfterStake);
    }
}

