        c = _c;
    }

    receive() external payable {}

    function run(uint256 amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        // Reject inputs that would overflow the reward math or total supply
        require(amount <= type(uint128).max, "amount too large");

        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        // Provide the staking tokens to this test contract, then stake.
        // The test contract is the only staker here, so msg.sender == address(this).
        require(amount == 0 || address(this).balance >= amount, "no balance");

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 amountBefore = amount;

        // Perform the stake. The staking token transfer must succeed for this
        // call to be meaningful; use try/catch so we only assert on success.
        bool reverted;
        try c.stake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // The staking token must have been transferred in, and accounting
            // must reflect the full staked amount.
            assert(
                c.totalSupply() == supplyBefore + amountBefore &&
                c.balanceOf(address(this)) == balanceBefore + amountBefore
            );
        } else {
            // On failure the accounting must be unchanged.
            assert(
                c.totalSupply() == supplyBefore &&
                c.balanceOf(address(this)) == balanceBefore
            );
        }
    }
}

