contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0);

        // Record the staker's own starting balance and the total supply of a fresh
        // account before the stake, so the rule can compare deltas for THIS staker.
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeTotalSupply = c.totalSupply();

        // Only the balance held by this staker is what the staking contract credits.
        // We use a staker that is only this test contract; a delta in that staker's
        // balance is exactly the amount staked on success.  Do NOT compare total
        // supply if this account already had a non-zero stake before the call,
        // because the preexisting balance makes the supply delta ambiguous.
        bool reverted;
        try c.stakeFor(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterTotalSupply = c.totalSupply();

        // General rule: on a successful stakeFor the staker's balance moves up by
        // exactly amount.  When the staker had no balance beforehand, the total
        // supply also rises by exactly amount.  We express the second part only
        // for the zero-before case to avoid the ambiguous mixed delta.
        assert(
            reverted ||
                (afterBalance - beforeBalance == amount &&
                    (beforeBalance != 0 || afterTotalSupply - beforeTotalSupply == amount))
        );
    }

    receive() external payable {}
}

