        // Record the observable state before staking.
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        // Perform the state-changing call as its own top-level statement.
        c.stakeAll();

        // Read the observable state after staking.
        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        uint256 tokenBalAfter = st.balanceOf(address(this));

        // General rule: stakeAll stakes the caller's entire starting token balance.
        assert(
            balAfter == balBefore + beforeBal &&
            supplyAfter == supplyBefore + beforeBal &&
            tokenBalAfter == 0
        );
    }

