        c = _c;
    }

    function run(address account, address rewardToken, uint256 amount, bool claim) public payable {
        require(account != address(0), "zero account");

        // If there is a reward token configured, and the caller has some staked balance,
        // reward accrual may make earned() non-decreasing under an updateReward call.
        // We make the deciding call be c.getRewards(account), which triggers updateReward(account).
        // Before the call, record the claimable amount observed through the public getter.
        uint256 beforeClaimable = c.claimableRewards(account, rewardToken);

        // Update rewards: this settles the staker's accrued rewards into claimableRewards.
        c.getRewards(account);

        // After the update, earned() should be at least the amount that was claimable before,
        // because claimableRewards is only increased by accrued rewards during updateReward.
        uint256 afterEarned = c.earned(account, rewardToken);

        assert(afterEarned >= beforeClaimable);
    }

    receive() external payable {}
}

