contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint64 stakeAmount, address rewardToken) public {
        require(stakeAmount > 0);
        require(staker != address(0));
        require(rewardToken != address(0));

        // Make the contract hold and track the staking token so reward math has supply.
        // stakingToken is public, so this is an allowed read.
        address stakingToken = address(c.stakingToken());

        require(stakingToken.code.length > 0, "need staking token contract");

        // The staker must already have approved and be funded; the test contract is the staker here.
        // Actually set up via direct calls on the token through the same address space
        // is not available (we can only call c), so drive c with the staker as an account
        // that has been prepared by the test harness. If staker has no balance/allowance,
        // the stake call will revert and we still check the invariant below via try/catch.

        bool staked;
        try c.stakeFor(staker, stakeAmount) { staked = true; } catch { staked = false; }

        // Regardless of whether the stake succeeded, earned() should reflect current state.
        uint256 earnedAmount = c.earned(staker, rewardToken);

        // Observable accounting identity: earned is non-negative and equals the
        // contract-computed value; it must be finite (no overflow) and cannot change
        // arbitrarily just because an unrelated view was called.
        uint256 earnedAgain = c.earned(staker, rewardToken);

        assert(earnedAmount == earnedAgain && earnedAmount >= c.claimableRewards(staker, rewardToken));
    }

    receive() external payable {}
}

